61	    /** 创建实验（仅 COORDINATOR）；区组数量 2~8，创建后不可改。 */
62	    @PostMapping("/experiments/{experimentId}")
63	    public ResponseEntity<String> createExperiment(
64	            @PathVariable String experimentId,
