53	     */
54	    public IdempotentRow lockByRequestId(String requestId) {
55	        List<IdempotentRow> rows = jdbc.query(
56	                "SELECT request_id, actor_id, role, operation, fingerprint, response_status, "
57	                        + "response_body, created_at FROM idempotent_request WHERE request_id = ? FOR UPDATE",
