66	                        + ") VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
67	                row.requestId(), row.actorId(), row.role(), row.operation(), row.fingerprint(),
68	                row.responseStatus(), row.responseBody(), row.createdAt());
69	    }
