74	    public void updateResult(String requestId, int responseStatus, String responseBody) {
75	        jdbc.update("UPDATE idempotent_request SET response_status = ?, response_body = ? "
76	                + "WHERE request_id = ?", responseStatus, responseBody, requestId);
77	    }
78	}
