void extensionConcurrentWithRegistrations_whenFull_exactlyCapacityNewSucceed()
        throws Exception {
    createExperiment("CE-2", 2, "ce2-create");
    registerUntilFull("CE-2", 8, "ce2-alloc-");

    // 1 个扩容（新增 4 席）与 8 个新参与者登记同时发起；登记均持有不同 requestId。
    int registrars = 8;
